import java.util.*;

class MCFGraphIntCost {
    private int n;
    private List<List<Edge>> g;
    private List<int[]> pos;
    private int[] dual;
    private int[] dist;
    private int[] pv;
    private int[] pe;
    private boolean[] vis;

    public MCFGraphIntCost(int n) {
        this.n = n;
        this.g = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            this.g.add(new ArrayList<>());
        }
        this.pos = new ArrayList<>();
    }

    public int addEdge(int from, int to, int cap, int cost) {
        int m = pos.size();
        pos.add(new int[]{from, g.get(from).size()});
        g.get(from).add(new Edge(to, g.get(to).size(), cap, cost));
        g.get(to).add(new Edge(from, g.get(from).size() - 1, 0, -cost));
        return m;
    }

    public Edge getEdge(int i) {
        Edge e = g.get(pos.get(i)[0]).get(pos.get(i)[1]);
        Edge re = g.get(e.to).get(e.rev);
        return new Edge(pos.get(i)[0], e.to, e.cap + re.cap, re.cap, e.cost);
    }

    public List<Edge> edges() {
        List<Edge> ret = new ArrayList<>();
        for (int i = 0; i < pos.size(); i++) {
            Edge e = g.get(pos.get(i)[0]).get(pos.get(i)[1]);
            Edge re = g.get(e.to).get(e.rev);
            ret.add(new Edge(pos.get(i)[0], e.to, e.cap + re.cap, re.cap, e.cost));
        }
        return ret;
    }

    private boolean dualRef(int s, int t) {
        dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        pv = new int[n];
        Arrays.fill(pv, -1);
        pe = new int[n];
        Arrays.fill(pe, -1);
        vis = new boolean[n];

        PriorityQueue<Long> que = new PriorityQueue<>();
        que.add((long) s);
        dist[s] = 0;
        while (!que.isEmpty()) {
            int v = (int) (que.poll() & 0xFFFFFFFFL);
            if (vis[v]) {
                continue;
            }
            vis[v] = true;
            if (v == t) {
                break;
            }
            for (int i = 0; i < g.get(v).size(); i++) {
                Edge e = g.get(v).get(i);
                if (vis[e.to] || e.cap == 0) {
                    continue;
                }
                int cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    que.add((long) (dist[e.to] << 32) + e.to);
                }
            }
        }
        if (!vis[t]) {
            return false;
        }

        for (int v = 0; v < n; v++) {
            if (!vis[v]) {
                continue;
            }
            dual[v] -= dist[t] - dist[v];
        }

        return true;
    }

    public List<int[]> slope(int s, int t, int flowLimit) {
        dual = new int[n];
        dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        pv = new int[n];
        Arrays.fill(pv, -1);
        pe = new int[n];
        Arrays.fill(pe, -1);
        vis = new boolean[n];

        int flow = 0;
        int cost = 0;
        int prevCost = -1;
        List<int[]> result = new ArrayList<>();
        result.add(new int[]{flow, cost});
        while (flow < flowLimit) {
            if (!dualRef(s, t)) {
                break;
            }
            int c = flowLimit - flow;
            int v = t;
            while (v != s) {
                c = Math.min(c, g.get(pv[v]).get(pe[v]).cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                Edge e = g.get(pv[v]).get(pe[v]);
                e.cap -= c;
                g.get(v).get(e.rev).cap += c;
                v = pv[v];
            }
            int d = -dual[s];
            flow += c;
            cost += c * d;
            if (prevCost == d) {
                result.remove(result.size() - 1);
            }
            result.add(new int[]{flow, cost});
            prevCost = cost;
        }
        return result;
    }

    public int[] flow(int s, int t, int flowLimit) {
        return slope(s, t, flowLimit).get(slope(s, t, flowLimit).size() - 1);
    }

    private static class Edge {
        int to;
        int rev;
        int cap;
        int flow;
        int cost;

        public Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }

        public Edge(int from, int to, int cap, int flow, int cost) {
            this.to = to;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int a1 = scanner.nextInt();
        int a2 = scanner.nextInt();
        int a3 = scanner.nextInt();
        int b1 = scanner.nextInt();
        int b2 = scanner.nextInt();
        int b3 = scanner.nextInt();

        MCFGraphIntCost g = new MCFGraphIntCost(8);
        g.addEdge(0, 1, a1, 0);
        g.addEdge(0, 2, a2, 0);
        g.addEdge(0, 3, a3, 0);
        g.addEdge(4, 7, b1, 0);
        g.addEdge(5, 7, b2, 0);
        g.addEdge(6, 7, b3, 0);
        for (int i = 1; i < 4; i++) {
            for (int j = 4; j < 7; j++) {
                int cost = (j - i) % 3 == 1 ? 1 : 0;
                g.addEdge(i, j, Integer.MAX_VALUE, cost);
            }
        }

        int[] flowResult = g.flow(0, 7, Integer.MAX_VALUE);
        int ans1 = flowResult[1];

        int ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}
